#include <algorithm>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <vector>

// The library: C++ inside, C outside. Only C types cross the boundary.
extern "C" {

enum { QUANT_OK = 0, QUANT_EMPTY = 1, QUANT_BAD_ARG = 2, QUANT_FAILED = 3 };

int quant_vwap(const double* prices, const double* sizes, int64_t n, double* out) noexcept {
    if (n < 0) return QUANT_BAD_ARG;
    if (n == 0) return QUANT_EMPTY;  // before the pointers: an empty array's may be null
    if (prices == nullptr || sizes == nullptr || out == nullptr) return QUANT_BAD_ARG;
    double notional = 0.0, volume = 0.0;
    for (int64_t i = 0; i < n; ++i) {
        notional += prices[i] * sizes[i];
        volume += sizes[i];
    }
    if (volume <= 0.0) return QUANT_EMPTY;
    *out = notional / volume;  // results go out through a pointer
    return QUANT_OK;           // the return value is the status
}

int quant_median(const double* x, int64_t n, double* out) noexcept {
    if (n < 0) return QUANT_BAD_ARG;
    if (n == 0) return QUANT_EMPTY;
    if (x == nullptr || out == nullptr) return QUANT_BAD_ARG;
    try {
        std::vector<double> v(x, x + n);  // can throw std::bad_alloc
        std::sort(v.begin(), v.end());
        *out = n % 2 == 1 ? v[n / 2] : (v[n / 2 - 1] + v[n / 2]) / 2.0;
        return QUANT_OK;
    } catch (...) {  // an exception must never reach C or Python
        return QUANT_FAILED;
    }
}

}  // extern "C"

// The caller: what C, or Python through ctypes, would write.
int main() {
    const double prices[] = {192.10, 192.40, 192.25};
    const double sizes[] = {100, 200, 100};
    double result = 0.0;
    std::cout << std::fixed << std::setprecision(4);

    int rc = quant_vwap(prices, sizes, 3, &result);
    std::cout << "vwap: rc " << rc << ", " << result << '\n';
    rc = quant_median(prices, 3, &result);
    std::cout << "median: rc " << rc << ", " << result << '\n';
    std::cout << "vwap of nothing: rc " << quant_vwap(prices, sizes, 0, &result) << '\n';
    std::cout << "vwap with no output: rc " << quant_vwap(prices, sizes, 3, nullptr) << '\n';
    return 0;
}

