enum { QUANT_OK = 0, QUANT_EMPTY = 1, QUANT_BAD_ARG = 2 };

// Fills out[0..n-1] with the EWMA of x, and returns a status.
int quant_ewma_series(const double* x, int64_t n, double alpha, double* out) noexcept {
    if (n < 0 || !(alpha > 0.0 && alpha <= 1.0)) return QUANT_BAD_ARG;
    if (n == 0) return QUANT_EMPTY;  // x.data() of an empty vector may be null
