extern "C" {

enum { QUANT_OK = 0, QUANT_EMPTY = 1, QUANT_BAD_ARG = 2 };

struct QuantStats {  // ctypes.Structure copies this layout field by field
    int64_t count;
    double mean;
    double stdev;
};

int quant_stats(const double* x, int64_t n, QuantStats* out) noexcept {
    if (n < 0) return QUANT_BAD_ARG;
    if (n < 2) return QUANT_EMPTY;
    if (x == nullptr || out == nullptr) return QUANT_BAD_ARG;
    double mean = 0.0, m2 = 0.0;
    for (int64_t i = 0; i < n; ++i) {  // Welford, from the lesson on statistics
        const double d = x[i] - mean;
        mean += d / (i + 1);
        m2 += d * (x[i] - mean);
    }
    *out = QuantStats{n, mean, std::sqrt(m2 / (n - 1))};
    return QUANT_OK;
}

}  // extern "C"

static_assert(std::is_standard_layout_v<QuantStats> && std::is_trivially_copyable_v<QuantStats>,
              "a struct that crosses into C must be plain data");

int main() {
    std::cout << "sizeof " << sizeof(QuantStats) << ", offsets " << offsetof(QuantStats, count) << ' '
              << offsetof(QuantStats, mean) << ' ' << offsetof(QuantStats, stdev) << '\n';

    const double mids[] = {19275.25, 19275.50, 19275.00, 19275.75, 19276.00};
    QuantStats stats{};
    const int rc = quant_stats(mids, 5, &stats);
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "rc " << rc << ", count " << stats.count << ", mean " << stats.mean << ", stdev " << stats.stdev << '\n';
    std::cout << "one value: rc " << quant_stats(mids, 1, &stats) << '\n';
    return 0;
}

