#include <cstdint>
#include <iomanip>
#include <iostream>
#include <vector>

extern "C" {

enum { QUANT_OK = 0, QUANT_EMPTY = 1, QUANT_BAD_ARG = 2 };

struct QuantSpread {
    int64_t quotes;      // every quote passed in
    int32_t crossed;     // quotes with bid >= ask, left out of the spreads
    double mean_spread;  // ask - bid, averaged over the other quotes
    double max_spread;
};

int quant_spreads(const double* bid, const double* ask, int64_t n, QuantSpread* out) noexcept {
    if (n < 0) return QUANT_BAD_ARG;
    if (n == 0) return QUANT_EMPTY;
    if (bid == nullptr || ask == nullptr || out == nullptr) return QUANT_BAD_ARG;
    QuantSpread s{n, 0, 0.0, 0.0};
    double total = 0.0;
    for (int64_t i = 0; i < n; ++i) {
        const double spread = ask[i] - bid[i];
        if (spread <= 0.0) {
            ++s.crossed;
            continue;
        }
        total += spread;
        if (spread > s.max_spread) s.max_spread = spread;
    }
    if (s.crossed == n) return QUANT_EMPTY;
    s.mean_spread = total / (n - s.crossed);
    *out = s;
    return QUANT_OK;
}

}  // extern "C"

int main() {
    std::cout << "sizeof " << sizeof(QuantSpread) << ", offsets " << offsetof(QuantSpread, quotes) << ' '
              << offsetof(QuantSpread, crossed) << ' ' << offsetof(QuantSpread, mean_spread) << ' '
              << offsetof(QuantSpread, max_spread) << '\n';
    int64_t n = 0;
    std::cin >> n;
    std::vector<double> bid(n), ask(n);
    for (int64_t i = 0; i < n; ++i) std::cin >> bid[i] >> ask[i];

    QuantSpread s{};
