#include <cmath>
#include <cstdint>
#include <iomanip>
#include <iostream>

// What the C header shows: a type with no insides, and functions on pointers to it.
extern "C" {
struct QuantEwma;
QuantEwma* quant_ewma_new(double alpha) noexcept;
int quant_ewma_update(QuantEwma* h, double x) noexcept;
double quant_ewma_value(const QuantEwma* h) noexcept;
void quant_ewma_free(QuantEwma* h) noexcept;
}

// What only the C++ side sees.
int g_live = 0;  // handles not yet freed

struct QuantEwma {
    double alpha;
    double mean = 0.0;
    int64_t count = 0;
    explicit QuantEwma(double a) : alpha(a) { ++g_live; }
    ~QuantEwma() { --g_live; }
};

QuantEwma* quant_ewma_new(double alpha) noexcept {
    if (!(alpha > 0.0 && alpha <= 1.0)) return nullptr;
    try {
        return new QuantEwma(alpha);
    } catch (...) {  // std::bad_alloc stays on this side
        return nullptr;
    }
}

int quant_ewma_update(QuantEwma* h, double x) noexcept {
    if (h == nullptr) return 2;
    h->mean = h->count == 0 ? x : h->mean + h->alpha * (x - h->mean);
    ++h->count;
    return 0;
}

double quant_ewma_value(const QuantEwma* h) noexcept {
    return h == nullptr ? NAN : h->mean;
}

void quant_ewma_free(QuantEwma* h) noexcept {
    delete h;  // deleting nullptr does nothing
}

// The caller, as Python's wrapper class would drive it.
int main() {
    QuantEwma* h = quant_ewma_new(0.5);
    std::cout << "live handles: " << g_live << '\n';
    for (double mid : {100.0, 102.0, 101.0, 103.0}) {
        quant_ewma_update(h, mid);
    }
    std::cout << std::fixed << std::setprecision(2) << "ewma " << quant_ewma_value(h) << '\n';
    quant_ewma_free(h);
    std::cout << "bad alpha gives a null handle: " << (quant_ewma_new(1.5) == nullptr ? "yes" : "no") << '\n';
    std::cout << "update on null: rc " << quant_ewma_update(nullptr, 1.0) << '\n';
    std::cout << "live handles: " << g_live << '\n';
    return 0;
}

