#include <cstdint>
#include <iomanip>
#include <iostream>
#include <vector>

long g_calls = 0;  // calls across the boundary, the part Python pays for

extern "C" {

struct QuantEwma {
    double alpha;
    double mean;
    int64_t count;
};

int quant_ewma_update(QuantEwma* h, double x) noexcept {  // one tick per call
    ++g_calls;
    if (h == nullptr) return 2;
    h->mean = h->count++ == 0 ? x : h->mean + h->alpha * (x - h->mean);
    return 0;
}

int quant_ewma_update_many(QuantEwma* h, const double* x, int64_t n) noexcept {  // a whole array
    ++g_calls;
    if (h == nullptr || n < 0 || (n > 0 && x == nullptr)) return 2;
    double mean = h->mean;  // work in a local, store once
    for (int64_t i = 0; i < n; ++i) {
        mean = h->count++ == 0 ? x[i] : mean + h->alpha * (x[i] - mean);
    }
    h->mean = mean;
    return 0;
}

}  // extern "C"

int main() {
    std::vector<double> mids(1000000);
    for (std::size_t i = 0; i < mids.size(); ++i) {
        mids[i] = 19275.0 + static_cast<double>(i % 11) * 0.25;
    }
    std::cout << std::fixed << std::setprecision(6);

    QuantEwma per_tick{0.1, 0.0, 0};
    for (double x : mids) {
        quant_ewma_update(&per_tick, x);
    }
    std::cout << "per tick: " << g_calls << " calls, ewma " << per_tick.mean << '\n';

    g_calls = 0;
    QuantEwma batch{0.1, 0.0, 0};
    quant_ewma_update_many(&batch, mids.data(), static_cast<int64_t>(mids.size()));
    std::cout << "batch:    " << g_calls << " call, ewma " << batch.mean << '\n';
    return 0;
}

