#include <cstdint>
#include <iomanip>
#include <iostream>
#include <vector>

long g_calls = 0;

extern "C" {

// One return per call, in basis points: 1 bp is 0.01%.
double quant_return_bps(double prev, double cur) noexcept {
    ++g_calls;
    return prev > 0.0 ? (cur - prev) / prev * 10000.0 : 0.0;
}

// Every return of n prices in one call: out[i - 1] for prices i - 1 and i.
int quant_returns_bps(const double* prices, int64_t n, double* out) noexcept {
    ++g_calls;
    if (n < 0) return 2;
    if (n < 2) return 1;
    if (prices == nullptr || out == nullptr) return 2;
    for (int64_t i = 1; i < n; ++i) {
        const double prev = prices[i - 1];
        out[i - 1] = prev > 0.0 ? (prices[i] - prev) / prev * 10000.0 : 0.0;
    }
    return 0;
}

}  // extern "C"

int main() {
    int64_t n = 0;
    std::cin >> n;
    std::vector<double> prices(n);
    for (double& p : prices) std::cin >> p;
    const int64_t m = n > 1 ? n - 1 : 0;

    std::vector<double> one_by_one(m), batch(m);
    for (int64_t i = 1; i < n; ++i) {
        one_by_one[i - 1] = quant_return_bps(prices[i - 1], prices[i]);
    }
    std::cout << "one by one: " << g_calls << " calls\n";

    g_calls = 0;
    const int rc = quant_returns_bps(prices.data(), n, batch.data());
    std::cout << "batch: " << g_calls << " call, rc " << rc << '\n';
    std::cout << std::fixed << std::setprecision(2);
    for (double r : batch) std::cout << r << " bp\n";
    std::cout << "same results: " << (batch == one_by_one ? "yes" : "no") << '\n';
    return 0;
}
